fn add_roles(
    funders: &mut Vec<FunderObservation>,
    member: MemberAsId,
    declaration: &CapturedDeclaration,
    scope_id: &str,
    source: impl Fn() -> FunderObservationSource,
    donor: Option<&str>,
    payer: Option<&str>,
    ultimate: Option<&str>,
    kind: Option<&str>,
    company: Option<&str>,
